interface.definition:
a!localVariables(
  local!firstName,
  local!lastName,
  local!email,
  #"SYSTEM_SYSRULES_formLayout_v1"(
    label: "TEST add user",
    contents: {
      #"SYSTEM_SYSRULES_textField"(
        label: "first name",
        value: local!firstName,
        saveInto: local!firstName
      ),
      #"SYSTEM_SYSRULES_textField"(
        label: "last name",
        value: local!lastName,
        saveInto: local!lastName
      ),
      #"SYSTEM_SYSRULES_textField"(
        label: "email",
        value: local!email,
        saveInto: local!email
      )
    },
    buttons: #"SYSTEM_SYSRULES_ButtonLayout"(
      primaryButtons: #"SYSTEM_SYSRULES_ButtonWidget"(
        label: "submit",
        saveInto: #"SYSTEM_SYSRULES_startProcess"(
          processModel: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3932301",
          processParameters: {
            firstName: local!firstName,
            lastName: local!lastName,
            username: local!email
          }
        )
      )
    )
  )
)
